"""Compile the player-facing chapter names; execution remains in typed Rust logic."""
import csv
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / 'docs' / 'chapters.tsv'
DESTINATION = ROOT / 'src' / 'chapter_catalog.rs'

def main():
    rows = list(csv.DictReader(SOURCE.open(encoding='utf-8-sig'), delimiter='\t'))
    assert len(rows) == 72
    lines = [
        '// Generated by tools/compile_chapter_catalog.py from docs/chapters.tsv.',
        'pub struct Chapter { pub id: &\'static str, pub title: &\'static str, pub after: &\'static [&\'static str], pub earliest_day: u64 }',
        'pub const CHAPTERS: [Chapter; 72] = [',
    ]
    for index, row in enumerate(rows, 1):
        assert row['章节ID'] == f'Q{index:02}'
        deps = row['前置章节全部满足'].replace('—', '').split(',')
        deps = [d for d in deps if d]
        assert all(0 < int(d[1:]) <= 72 and d != row['章节ID'] for d in deps)
        quote = lambda s: json.dumps(s, ensure_ascii=False)
        lines.append('    Chapter { id: %s, title: %s, after: &[%s], earliest_day: %d },' % (
            quote(row['章节ID']), quote(row['标题']), ','.join(map(quote, deps)), int(row['最早世界日龄'])))
    lines.append('];\n')
    DESTINATION.write_text('\n'.join(lines), encoding='utf-8')

if __name__ == '__main__':
    main()
